                      onPress={toggleCameraFacing}
                      activeOpacity={0.7}
                      accessibilityRole="button"
                      accessibilityLabel="Switch camera"
                    >
                      <SwitchCamera size={24} color={textColor} />
                    </TouchableOpacity>
                    <TouchableOpacity
                      style={[
                        styles.controlButton,
                        {
                          backgroundColor: zoomControls
                            ? primaryColor
                            : cardColor,
