                      ]}
                      onPress={handleZoomButtonTap}
                      activeOpacity={0.7}
                      accessibilityRole="button"
                      accessibilityLabel="Cycle zoom level"
                    >
                      <NexGText
                        variant="body"
                        style={{
                          fontWeight: "600",
                          color: zoomControls ? cardColor : textColor,
