                      >
                        {zoomFactorText}
                      </NexGText>
                    </TouchableOpacity>
                    {enableVideo && (
                      <TouchableOpacity
                        style={[
                          styles.controlButton,
                          { backgroundColor: cardColor },
                        ]}
                        onPress={toggleMode}
                        disabled={isRecording || isCapturing}
                        activeOpacity={0.7}
