                          <CameraIcon size={24} color={textColor} />
                        )}
                      </TouchableOpacity>
                    )}
                  </View>
                  <View style={styles.bottomControls}>
                    <TouchableOpacity
                      style={[
                        styles.captureButton,
                        {
                          backgroundColor:
                            mode === "video" && isRecording
                              ? destructiveColor
                              : "white",
                          borderColor:
                            mode === "video" && isRecording
                              ? destructiveColor
                              : primaryColor,
                        },
                        (isCapturing || isTimerActive) &&
                          styles.capturingButton,
                      ]}
                      onPress={
                        mode === "picture"
                          ? handleCapture
                          : isRecording
                            ? handleStopRecording
                            : handleCapture
                      }
                      disabled={isCapturing || isTimerActive}
                      activeOpacity={0.8}
                      accessibilityRole="button"
                      accessibilityLabel={
                        mode === "video"
                          ? isRecording
                            ? "Stop recording"
                            : "Start recording"
                          : "Take picture"
                      }
                    >
                      {isCapturing ? (
                        <ActivityIndicator size="small" color={primaryColor} />
                      ) : (
                        <View
                          style={[
                            styles.captureInner,
                            {
                              backgroundColor:
