                                mode === "video" && isRecording ? 4 : 30,
                            },
                          ]}
                        />
                      )}
                    </TouchableOpacity>
                  </View>
                </>
              )}
            </AnimatedCameraView>
          </GestureDetector>
        </View>
      </Animated.View>
