import { useTheme } from '@/theme';
import React, { useEffect, useState } from 'react';
import { Modal, StyleSheet, View } from 'react-native';
import Animated, { Easing, ReduceMotion, useAnimatedStyle, useSharedValue, withTiming } from 'react-native-reanimated';
import { NexGButton } from './NexGButton';
import { NexGText } from './NexGText';

interface NexGConfirmProps {
  open: boolean;
  title: string;
  message: string;
  confirmLabel: string;
  onConfirm: () => void;
  onClose: () => void;
  destructive?: boolean;
  loading?: boolean;
}

/**
 * Destructive-action confirmation. Modals stay centered (scale-origin exempt),
 * enter from scale(0.96)+opacity, and exit faster than they enter.
 */
export const NexGConfirm = ({
  open,
  title,
  message,
  confirmLabel,
  onConfirm,
  onClose,
  destructive = true,
  loading = false,
}: NexGConfirmProps) => {
  const { colors, radii, spacing } = useTheme();
  const [mounted, setMounted] = useState(open);
  const progress = useSharedValue(0);

  useEffect(() => {
    if (open) {
      setMounted(true);
      progress.value = withTiming(1, { duration: 200, easing: Easing.out(Easing.cubic), reduceMotion: ReduceMotion.System });
    } else if (mounted) {
      progress.value = withTiming(0, { duration: 140, easing: Easing.out(Easing.cubic), reduceMotion: ReduceMotion.System });
      const t = setTimeout(() => setMounted(false), 150);
      return () => clearTimeout(t);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  const backdropStyle = useAnimatedStyle(() => ({ opacity: progress.value }));
  const cardStyle = useAnimatedStyle(() => ({
    opacity: progress.value,
    transform: [{ scale: 0.96 + 0.04 * progress.value }],
  }));

  if (!mounted) return null;

  return (
    <Modal transparent visible onRequestClose={onClose} animationType="none">
      <View style={StyleSheet.absoluteFill}>
        <Animated.View style={[StyleSheet.absoluteFill, { backgroundColor: colors.overlay }, backdropStyle]} />
        <View style={styles.center}>
          <Animated.View
            style={[
              styles.card,
              cardStyle,
              { backgroundColor: colors.surface.primary, borderRadius: radii.large, padding: spacing.xl },
            ]}>
            <NexGText variant="heading" align="center">
              {title}
            </NexGText>
            <NexGText variant="body" color="secondary" align="center" style={{ marginTop: spacing.sm }}>
              {message}
            </NexGText>
            <View style={{ marginTop: spacing.xl, gap: spacing.sm }}>
              <NexGButton
                label={loading ? 'Processing…' : confirmLabel}
                variant={destructive ? 'destructive' : 'primary'}
                onPress={onConfirm}
                loading={loading}
              />
              <NexGButton label="Go back" variant="secondary" onPress={onClose} />
            </View>
          </Animated.View>
        </View>
      </View>
    </Modal>
  );
};

const styles = StyleSheet.create({
  center: {
    ...StyleSheet.absoluteFill,
    alignItems: 'center',
    justifyContent: 'center',
    padding: 32,
  },
  card: {
    width: '100%',
    maxWidth: 340,
    shadowColor: '#000',
    shadowOpacity: 0.2,
    shadowRadius: 20,
    shadowOffset: { width: 0, height: 8 },
    elevation: 12,
  },
});

import { NexGButton } from '@/components/ui/NexGButton';
import { NexGText } from '@/components/ui/NexGText';
import React, { Component, ErrorInfo, ReactNode } from 'react';
import { StyleSheet, View } from 'react-native';

interface Props {
  children: ReactNode;
  fallbackMessage?: string;
}

interface State {
  hasError: boolean;
}

/**
 * ErrorBoundary — last line of defense so a malformed item can never black out
 * the whole screen. If a child render throws, we surface a graceful fallback
 * with a way back instead of a blank/black modal.
 */
export class ErrorBoundary extends Component<Props, State> {
  state: State = { hasError: false };

  static getDerivedStateFromError(): State {
    return { hasError: true };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    // Surfaced in dev; in production this keeps the app usable.
    console.warn('[NexG] Item experience error:', error?.message, info?.componentStack?.slice(0, 400));
  }

  reset = () => this.setState({ hasError: false });

  render() {
    if (this.state.hasError) {
      return (
        <View style={styles.fallback}>
          <NexGText variant="heading" style={{ marginBottom: 8 }}>
            We couldn't show this
          </NexGText>
          <NexGText variant="body" color="muted" style={{ marginBottom: 16, textAlign: 'center' }}>
            {this.props.fallbackMessage ?? 'This item has a problem. Please try another.'}
          </NexGText>
          <NexGButton label="Go back" variant="secondary" size="medium" onPress={this.reset} />
        </View>
      );
    }
    return this.props.children;
  }
}

const styles = StyleSheet.create({
  fallback: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
    padding: 32,
    gap: 4,
  },
});

import React from 'react';
import { Pressable, StyleSheet, Text, View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import Animated, { Easing, interpolateColor, useAnimatedStyle, useReducedMotion, useSharedValue, withTiming } from 'react-native-reanimated';
import { fontFamilies, useTheme } from '@/theme';
import { usePressScale } from '@/hooks/use-press-scale';
import { triggerHaptic } from '@/hooks/use-haptics';

const ENTER_EASING = Easing.bezier(0.23, 1, 0.32, 1);

type TabIcon = (args: { focused: boolean; color: string; size: number }) => React.ReactNode;

interface PillTabItemProps {
  label: string;
  accessibilityLabel: string;
  focused: boolean;
  icon: TabIcon;
  activeColor: string;
  inactiveColor: string;
  pillFrom: string;
  pillTo: string;
  onPress: () => void;
  onLongPress: () => void;
}

function PillTabItem({
  label,
  accessibilityLabel,
  focused,
  icon,
  activeColor,
  inactiveColor,
  pillFrom,
  pillTo,
  onPress,
  onLongPress,
}: PillTabItemProps) {
  const reduceMotion = useReducedMotion();
  const progress = useSharedValue(focused ? 1 : 0);
  const { pressHandlers, pressStyle: sharedPressStyle } = usePressScale(0.97);

  React.useEffect(() => {
    if (reduceMotion) {
      progress.value = focused ? 1 : 0;
    } else {
      progress.value = withTiming(focused ? 1 : 0, { duration: 200, easing: ENTER_EASING });
    }
  }, [focused, progress, reduceMotion]);

  const pillStyle = useAnimatedStyle(() => ({
    backgroundColor: interpolateColor(progress.value, [0, 1], [pillFrom, pillTo]),
  }));

  const contentColor = focused ? activeColor : inactiveColor;

  return (
    <Pressable
      accessibilityRole="button"
      accessibilityState={{ selected: focused }}
      accessibilityLabel={accessibilityLabel}
      onPress={onPress}
      onLongPress={onLongPress}
      {...pressHandlers}
      style={styles.itemHit}
    >
      <Animated.View style={[styles.itemPill, pillStyle, sharedPressStyle]}>
        {icon({ focused, color: contentColor, size: 22 })}
        <Text style={[styles.itemLabel, { color: contentColor }]} numberOfLines={1}>
          {label}
        </Text>
      </Animated.View>
    </Pressable>
  );
}

/**
 * Floating pill tab bar (in-flow, never overlays screen content).
 * Active tab crossfades to a filled pill on the UI thread; press gives
 * 0.97-scale feedback + one haptic on commit. Honors reduced motion.
 *
 * Props are a narrow owned contract (not the vendored navigator types), so
 * this bar works with any tab router that supplies routes + descriptors.
 */
export interface NexGPillTabBarProps {
  state: { index: number; routes: Array<{ key: string; name: string }> };
  descriptors: PillBarDescriptorMap;
  navigation: PillBarNavigation;
}

interface PillBarDescriptorMap {
  [key: string]: PillBarDescriptor;
}

interface PillBarDescriptor {
  options: {
    title?: string;
    tabBarAccessibilityLabel?: string;
    tabBarIcon?: (args: { focused: boolean; color: string; size: number }) => React.ReactNode;
  };
}

interface PillBarNavigation {
  emit: (event: PillBarEvent) => void;
  navigate: (name: string) => void;
}

interface PillBarEvent {
  type: 'tabPress' | 'tabLongPress';
  target: string;
  canPreventDefault: boolean;
}

export function NexGPillTabBar({ state, descriptors, navigation }: NexGPillTabBarProps) {
  const { colors } = useTheme();
  const insets = useSafeAreaInsets();

  return (
    <View style={[styles.root, { backgroundColor: colors.background.primary, paddingBottom: insets.bottom + 12 }]}>
      <View
        accessibilityRole="tablist"
        style={[styles.pill, { backgroundColor: colors.surface.primary, borderColor: colors.border.subtle }]}
      >
        {state.routes.map((route, index) => {
          const options = descriptors[route.key].options;
          const label = options.title ?? route.name;
          const focused = state.index === index;
          const icon = options.tabBarIcon;
          if (!icon) return null;
          const itemIcon: TabIcon = (args) => icon(args);
          return (
            <PillTabItem
              key={route.key}
              label={label}
              accessibilityLabel={options.tabBarAccessibilityLabel ?? label}
              focused={focused}
              icon={itemIcon}
              activeColor={colors.text.inverse}
              inactiveColor={colors.text.muted}
              pillFrom={colors.surface.primary}
              pillTo={colors.action.primary}
              onPress={() => {
                // No tabPress listeners exist in these apps, so navigate
                // directly after emitting (no defaultPrevented to honor).
                if (focused) return;
                navigation.emit({ type: 'tabPress', target: route.key, canPreventDefault: true });
                navigation.navigate(route.name);
                triggerHaptic('selection');
              }}
              onLongPress={() => navigation.emit({ type: 'tabLongPress', target: route.key, canPreventDefault: true })}
            />
          );
        })}
      </View>
    </View>
  );
}

