// AUTO-SYNCED from packages/shared — edit there, then run node scripts/sync-shared.js
// Promoted from vendor/ahmedbna-ui-components (registry/src/components/ui/toast.tsx).
// Adaptations: NexG theme tokens (surface.inverse island, status.* variants) instead of
// the fixed iOS-dark palette so toasts read in light + dark mode; NexGText slots.
// Behavior preserved: Dynamic Island expand/collapse, spring entry, swipe-to-dismiss,
// provider show() API shape, stacked offsets, a11y alert role + live region.
import { NexGText } from '@/components/ui/NexGText';
import { useTheme } from '@/theme';
import { AlertCircle, Check, Info, X } from 'lucide-react-native';
import React, {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useState,
} from 'react';
import {
  AccessibilityInfo,
  Dimensions,
  Platform,
  TouchableOpacity,
  View,
  ViewStyle,
} from 'react-native';
import {
  Gesture,
  GestureDetector,
  GestureHandlerRootView,
} from 'react-native-gesture-handler';
import Animated, {
  runOnJS,
  useAnimatedStyle,
  useSharedValue,
  withDelay,
  withSpring,
  withTiming,
} from 'react-native-reanimated';

export type NexGToastVariant =
  | 'default'
  | 'success'
  | 'error'
  | 'warning'
  | 'info';

export interface NexGToastData {
  id: string;
  title?: string;
  description?: string;
  variant?: NexGToastVariant;
  duration?: number;
  action?: {
    label: string;
    onPress: () => void;
  };
}

export interface NexGToastProps extends NexGToastData {
  onDismiss: (id: string) => void;
  index: number;
}

const { width: screenWidth } = Dimensions.get('window');
const DYNAMIC_ISLAND_HEIGHT = 37;
const EXPANDED_HEIGHT = 85;
const TOAST_MARGIN = 8;
const DYNAMIC_ISLAND_WIDTH = 126;
const EXPANDED_WIDTH = screenWidth - 32;

// Reanimated spring configuration
const SPRING_CONFIG = {
  stiffness: 120,
  damping: 8,
};

export function NexGToast({
  id,
  title,
  description,
  variant = 'default',
  onDismiss,
  index,
  action,
}: NexGToastProps) {
  const { colors, spacing } = useTheme();
  const [isExpanded, setIsExpanded] = useState(false);
  const [reduceMotion, setReduceMotion] = useState(false);

  useEffect(() => {
    AccessibilityInfo.isReduceMotionEnabled().then(setReduceMotion);
    const subscription = AccessibilityInfo.addEventListener(
      'reduceMotionChanged',
      setReduceMotion
    );
    return () => subscription.remove();
  }, []);

  // Reanimated shared values
  const translateY = useSharedValue(-100);
  const translateX = useSharedValue(0);
  const opacity = useSharedValue(0);
  const scale = useSharedValue(0.8);
  const width = useSharedValue(DYNAMIC_ISLAND_WIDTH);
  const height = useSharedValue(DYNAMIC_ISLAND_HEIGHT);
  const borderRadius = useSharedValue(18.5);
  const contentOpacity = useSharedValue(0);

  // Island surface stays contrasted against the app background in both modes.
  const islandBg = colors.surface.inverse;
  const mutedColor = colors.text.muted;

  useEffect(() => {
    const hasContentToShow = Boolean(title || description || action);

    if (hasContentToShow) {
      // If there's content, start directly with expanded state
      width.value = EXPANDED_WIDTH;
      height.value = EXPANDED_HEIGHT;
      borderRadius.value = 20;
      setIsExpanded(true);

      if (reduceMotion) {
        translateY.value = 0;
        opacity.value = 1;
        scale.value = 1;
        contentOpacity.value = 1;
      } else {
        // Animate in expanded toast
        translateY.value = withSpring(0, SPRING_CONFIG);
        opacity.value = withTiming(1, { duration: 300 });
        scale.value = withSpring(1, SPRING_CONFIG);
        contentOpacity.value = withDelay(100, withTiming(1, { duration: 300 }));
      }
    } else {
      // If no content, show compact Dynamic Island with icon only
      setIsExpanded(false);

      if (reduceMotion) {
        translateY.value = 0;
        opacity.value = 1;
        scale.value = 1;
      } else {
        // Animate in compact toast
        translateY.value = withSpring(0, SPRING_CONFIG);
        opacity.value = withTiming(1, { duration: 200 });
        scale.value = withSpring(1, SPRING_CONFIG);
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [reduceMotion]); // Re-run if the reduced-motion setting resolves after mount

  const getVariantColor = () => {
    switch (variant) {
      case 'success':
        return colors.status.success;
      case 'error':
        return colors.status.error;
      case 'warning':
        return colors.status.warning;
      case 'info':
        return colors.status.info;
      default:
        return mutedColor;
    }
  };

  const getIcon = () => {
    const iconProps = { size: 16, color: getVariantColor(), strokeWidth: 2 };

    switch (variant) {
      case 'success':
        return <Check {...iconProps} />;
      case 'error':
        return <X {...iconProps} />;
      case 'warning':
        return <AlertCircle {...iconProps} />;
      case 'info':
        return <Info {...iconProps} />;
      default:
        return null;
    }
  };

  const dismiss = useCallback(() => {
    if (reduceMotion) {
      onDismiss(id);
      return;
    }

    // This function will be called from the UI thread
    const onDismissAction = () => {
      'worklet';
      runOnJS(onDismiss)(id);
    };

    translateY.value = withSpring(-100, SPRING_CONFIG);
    opacity.value = withTiming(0, { duration: 250 }, (finished) => {
      if (finished) {
        onDismissAction();
      }
    });
    scale.value = withSpring(0.8, SPRING_CONFIG);
  }, [id, onDismiss, reduceMotion, translateY, opacity, scale]);

  const panGesture = Gesture.Pan()
    .onUpdate((event) => {
      // Reduced motion: swipe-to-dismiss still works (below), it just
      // doesn't visually track the finger.
      if (reduceMotion) return;
      translateX.value = event.translationX;
    })
    .onEnd((event) => {
      const { translationX, velocityX } = event;

      if (
        Math.abs(translationX) > screenWidth * 0.25 ||
        Math.abs(velocityX) > 800
      ) {
        if (reduceMotion) {
          runOnJS(onDismiss)(id);
          return;
        }

        // Dismiss action to be called from the UI thread
        const onDismissAction = () => {
          'worklet';
          runOnJS(onDismiss)(id);
        };

        // Animate out horizontally
        translateX.value = withTiming(
          translationX > 0 ? screenWidth : -screenWidth,
          { duration: 250 }
        );
        opacity.value = withTiming(0, { duration: 250 }, (finished) => {
          if (finished) {
            onDismissAction();
          }
        });
      } else if (!reduceMotion) {
        // Snap back with spring animation
        translateX.value = withSpring(0, SPRING_CONFIG);
      }
    });

  const getTopPosition = () => {
    const statusBarHeight = Platform.OS === 'ios' ? 59 : 20;
    return statusBarHeight + index * (EXPANDED_HEIGHT + TOAST_MARGIN);
  };

  // Animated styles
  const animatedContainerStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
    transform: [
      { translateY: translateY.value },
      { translateX: translateX.value },
      { scale: scale.value },
    ],
  }));

  const animatedIslandStyle = useAnimatedStyle(() => ({
    width: width.value,
    height: height.value,
    borderRadius: borderRadius.value,
    backgroundColor: islandBg,
    justifyContent: 'center',
    alignItems: 'center',
    overflow: 'hidden',
  }));

  const animatedContentStyle = useAnimatedStyle(() => ({
    opacity: contentOpacity.value,
  }));

  const toastStyle: ViewStyle = {
    position: 'absolute',
    top: getTopPosition(),
    alignSelf: 'center',
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 8 },
    shadowOpacity: 0.25,
    shadowRadius: 20,
    elevation: 10,
    zIndex: 1000 + index,
  };

  return (
    <GestureDetector gesture={panGesture}>
      <Animated.View
        style={[toastStyle, animatedContainerStyle]}
        accessible
        accessibilityRole="alert"
        accessibilityLiveRegion="polite"
        accessibilityLabel={[title, description].filter(Boolean).join('. ')}
      >
        <Animated.View style={animatedIslandStyle}>
          {/* Compact state - just icon or indicator */}
          {!isExpanded && (
            <View style={{ justifyContent: 'center', alignItems: 'center' }}>
              {getIcon()}
            </View>
          )}

          {/* Expanded state - full content */}
          {isExpanded && (
            <Animated.View
              style={[
                {
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  right: 0,
                  bottom: 0,
                  paddingHorizontal: spacing.lg,
                  paddingVertical: spacing.md,
                  flexDirection: 'row',
                  alignItems: 'center',
                },
                animatedContentStyle,
              ]}
            >
              {getIcon() && (
                <View style={{ marginRight: spacing.md }}>{getIcon()}</View>
              )}

              <View style={{ flex: 1, minWidth: 0 }}>
                {title && (
                  <NexGText
                    variant="bodyStrong"
                    color="inverse"
                    style={{ marginBottom: description ? 2 : 0 }}
                    numberOfLines={1}
                    ellipsizeMode="tail"
                  >
                    {title}
                  </NexGText>
                )}
                {description && (
                  <NexGText
                    variant="caption"
                    color="inverse"
                    style={{ fontSize: 13, opacity: 0.65 }}
                    numberOfLines={2}
                    ellipsizeMode="tail"
                  >
                    {description}
                  </NexGText>
                )}
              </View>

              {action && (
                <TouchableOpacity
                  onPress={action.onPress}
                  accessibilityRole="button"
                  accessibilityLabel={action.label}
                  style={{
                    marginLeft: spacing.md,
                    paddingHorizontal: spacing.md,
                    paddingVertical: 6,
                    minHeight: 44,
                    minWidth: 44,
                    justifyContent: 'center',
                    alignItems: 'center',
                    backgroundColor: getVariantColor(),
                    borderRadius: 8,
                  }}
                >
                  <NexGText variant="label" color="inverse">
                    {action.label}
                  </NexGText>
                </TouchableOpacity>
              )}

              <TouchableOpacity
                onPress={dismiss}
                accessibilityRole="button"
                accessibilityLabel="Dismiss"
                style={{
                  marginLeft: spacing.sm,
                  padding: spacing.xs,
                  minWidth: 44,
                  minHeight: 44,
                  justifyContent: 'center',
                  alignItems: 'center',
                  borderRadius: 8,
                }}
              >
                <X size={14} color={mutedColor} strokeWidth={2} />
              </TouchableOpacity>
            </Animated.View>
          )}
        </Animated.View>
      </Animated.View>
    </GestureDetector>
  );
}

interface NexGToastContextType {
  toast: (toast: Omit<NexGToastData, 'id'>) => void;
  success: (title: string, description?: string) => void;
  error: (title: string, description?: string) => void;
  warning: (title: string, description?: string) => void;
  info: (title: string, description?: string) => void;
  dismiss: (id: string) => void;
  dismissAll: () => void;
}

const NexGToastContext = createContext<NexGToastContextType | null>(null);

export interface NexGToastProviderProps {
  children: React.ReactNode;
  maxToasts?: number;
}

export function NexGToastProvider({
  children,
  maxToasts = 3,
}: NexGToastProviderProps) {
  const [toasts, setToasts] = useState<NexGToastData[]>([]);

  const generateId = () => Math.random().toString(36).substr(2, 9);

  const dismissToast = useCallback((id: string) => {
    setToasts((prev) => prev.filter((toast) => toast.id !== id));
  }, []);

  const dismissAll = useCallback(() => {
    setToasts([]);
  }, []);

  const addToast = useCallback(
    (toastData: Omit<NexGToastData, 'id'>) => {
      const id = generateId();
      const newToast: NexGToastData = {
        ...toastData,
        id,
        duration: toastData.duration ?? 4000,
      };

      setToasts((prev) => {
        const updated = [newToast, ...prev];
        return updated.slice(0, maxToasts);
      });

      // Auto dismiss after duration
      if (newToast.duration && newToast.duration > 0) {
        setTimeout(() => {
          dismissToast(id);
        }, newToast.duration);
      }
    },
    [maxToasts, dismissToast]
  );

  const createVariantToast = useCallback(
    (variant: NexGToastVariant, title: string, description?: string) => {
      addToast({
        title,
        description,
        variant,
      });
    },
    [addToast]
  );

  const contextValue: NexGToastContextType = {
    toast: addToast,
    success: (title, description) =>
      createVariantToast('success', title, description),
    error: (title, description) =>
      createVariantToast('error', title, description),
    warning: (title, description) =>
      createVariantToast('warning', title, description),
    info: (title, description) => createVariantToast('info', title, description),
    dismiss: dismissToast,
    dismissAll,
  };

  const containerStyle: ViewStyle = {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    zIndex: 1000,
    pointerEvents: 'box-none',
  };

  return (
    <NexGToastContext.Provider value={contextValue}>
      <GestureHandlerRootView style={{ flex: 1 }}>
        {children}
        <View style={containerStyle} pointerEvents="box-none">
          {toasts.map((toast, index) => (
            <NexGToast
              key={toast.id}
              {...toast}
              index={index}
              onDismiss={dismissToast}
            />
          ))}
        </View>
      </GestureHandlerRootView>
    </NexGToastContext.Provider>
  );
}

// Hook to use toast
export function useNexGToast() {
  const context = useContext(NexGToastContext);

  if (!context) {
    throw new Error('useNexGToast must be used within a NexGToastProvider');
  }

  return context;
}

// Shared messaging hooks — one live-threads system for every app.
// Poll contract (15s) + SSE live-invalidate, same as rider jobs; inbox-poll fallback
// lives inside the events client. Framework: React Query (present in all apps).
import { useEffect } from "react";
import { useQuery, useQueryClient, type UseQueryResult } from "@tanstack/react-query";
import { createMessagingClient, type ThreadSummary, type Message } from "@/lib/messaging";
import { createEventClient } from "@/lib/events";
import { apiBase, isApiEnabled, peekSessionToken } from "@/services/nexg/api";

export interface MessagingSetup {
  base: string;
  getToken: () => string | null;
  accountId?: () => string | null;
}

// Consumer-owned bridge: screens resolve backend + session from the local services
// layer (EXPO_PUBLIC_API_URL + session token cache) instead of threading config.
export function messagingSetup(): MessagingSetup | null {
  if (!isApiEnabled()) return null;
  return { base: apiBase(), getToken: peekSessionToken };
}

export { threadLabel } from "@/lib/messaging";
export type { Message, ThreadSummary } from "@/lib/messaging";

export function useSharedMessaging(setup: MessagingSetup) {
  const queryClient = useQueryClient();
  const client = createMessagingClient({ base: setup.base, getToken: setup.getToken });

  const threads: UseQueryResult<ThreadSummary[]> = useQuery({
    queryKey: ["msg-threads"],
    queryFn: () => client.listThreads(),
    refetchInterval: 15000, // poll contract: 15s backstop on every surface
  });

  // Live: subscribe entity channels (order:/booking: deep-link capability — never 403).
  // Merchant/property/rider channels are role-gated; those surfaces rely on the 15s poll.
  useEffect(() => {
    const keys = (threads.data ?? [])
      .map((t) => t.latest)
      .filter((m) => (m.entity_type === "order" || m.entity_type === "booking") && m.entity_id)
      .map((m) => `${m.entity_type}:${m.entity_id}`);
    if (!keys.length) return;
    const events = createEventClient({ base: setup.base, getToken: setup.getToken });
    const off = events.on("message.sent", () => {
      queryClient.invalidateQueries({ queryKey: ["msg-threads"] });
      queryClient.invalidateQueries({ queryKey: ["msg-thread"] });
    });
    events.connect([...new Set(keys)]);
    return () => {
      off();
      events.disconnect();
    };
  }, [queryClient, setup.base, setup.getToken, (threads.data ?? []).map((t) => t.thread_key).join(",")]);

  return { client, threads };
}

export function useThreadMessages(
  client: ReturnType<typeof createMessagingClient> | null,
  thread_key: string | null,
  enabled = true
): UseQueryResult<Message[]> {
  return useQuery({
    queryKey: ["msg-thread", thread_key],
    queryFn: () => {
      // `enabled` below already gates this query on both values, but re-checking here
      // keeps the narrowing local so a future contract shift fails loudly, not silently.
      if (!client || !thread_key) throw new Error("thread_not_ready");
      return client.listMessages(thread_key);
    },
    enabled: enabled && !!client && !!thread_key,
    refetchInterval: 15000,
  });
}

// AUTO-SYNCED from packages/shared — edit there, then run node scripts/sync-shared.js
// Client mirror of backend src/composer.ts — same weights, runs offline on cached data.
// Server (GET /discovery/home) wins when online; this wins when stale/offline.
export interface ComposerInput {
  activeOrders?: Array<{ id: string }>;
  upcomingBookings?: Array<{ id: string }>;
  urgentRequests?: Array<{ id: string }>;
  lastSearch?: string | null;
  nearbyOpen?: Array<{ id: string; name: string }>;
  personal?: Array<{ id: string; name: string }>;
  popular?: Array<{ id: string; name: string }>;
  promotions?: Array<{ id: string; title: string }>;
}

export function composeHome(input: ComposerInput) {
  const sections: Array<{ key: string; title: string; priority: number; items: unknown[] }> = [];
  if (input.activeOrders?.length)
    sections.push({ key: "active", title: "Active now", priority: 100, items: input.activeOrders });
  if (input.upcomingBookings?.length)
    sections.push({ key: "upcoming", title: "Up next", priority: 95, items: input.upcomingBookings });
  if (input.urgentRequests?.length)
    sections.push({ key: "urgent", title: "Needs attention", priority: 90, items: input.urgentRequests });
  if (input.lastSearch)
    sections.push({ key: "relevant", title: `For "${input.lastSearch}"`, priority: 85, items: [] });
  if (input.nearbyOpen?.length)
    sections.push({ key: "nearby", title: "Around you", priority: 70, items: input.nearbyOpen });
  if (input.personal?.length)
    sections.push({ key: "personal", title: "Recommended for you", priority: 65, items: input.personal });
  if (input.popular?.length)
    sections.push({ key: "popular", title: "Popular near you", priority: 50, items: input.popular });
  if (input.promotions?.length)
    sections.push({ key: "promos", title: "Offers", priority: 40, items: input.promotions });
  sections.push({ key: "discover", title: "Explore more", priority: 30, items: [] });
  return sections.sort((a, b) => b.priority - a.priority);
}

export function primaryActionFor(capabilities: string[]): string {
  if (capabilities.includes("order")) return "Order now";
  if (capabilities.includes("book")) return "Book now";
  if (capabilities.includes("reserve")) return "Reserve";
  if (capabilities.includes("quote")) return "Get ride";
  if (capabilities.includes("request")) return "Request service";
  return "View";
}

